const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY="eduworld_v3";let old={};try{old=JSON.parse(localStorage.getItem(KEY)||"{}")}catch{}
let state={completed:old.completed||[],points:old.points||0,tests:old.tests||0},subject="all",current=null,quiz=[],qi=0,score=0,answered=false,quizTarget="#quizContent",inlineQuizMode=false;
const letters=["أ","ب","ج","د"];
function save(){localStorage.setItem(KEY,JSON.stringify(state));stats()}
function stats(){
 $("#completedCount").textContent=state.completed.length;$("#pointsCount").textContent=state.points;$("#testsCount").textContent=state.tests;$("#rankCount").textContent="بعد الربط";
 $("#scienceLessonsCount").textContent=CURRICULUM.filter(x=>x.subject==="science").length;$("#studiesLessonsCount").textContent=CURRICULUM.filter(x=>x.subject==="studies").length;
 $("#scienceQuestionsCount").textContent=CURRICULUM.filter(x=>x.subject==="science").reduce((n,x)=>n+x.questions.length,0);
 $("#studiesQuestionsCount").textContent=CURRICULUM.filter(x=>x.subject==="studies").reduce((n,x)=>n+x.questions.length,0);
 $("#questionBankCount").textContent=CURRICULUM.reduce((n,x)=>n+x.questions.length,0);
}
function safe(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function notify(t){let x=$("#toast");x.textContent=t;x.classList.add("show");setTimeout(()=>x.classList.remove("show"),2200)}
function lesson(id){return CURRICULUM.find(x=>x.id===+id)}
function renderBoard(){$("#leaderboardList").innerHTML='<div class="empty-board"><div>🏆</div><b>لا يوجد طلاب في القائمة حاليًا</b><p>ستظهر أسماء الطلاب ونتائجهم الحقيقية بعد ربط قاعدة البيانات وتسجيل حسابات فعلية. لا توجد أسماء وهمية.</p></div>'}
function renderLessons(){
 let list=CURRICULUM.filter(x=>subject==="all"||x.subject===subject),units=[...new Set(list.map(x=>x.unit))];
 $("#lessonGrid").innerHTML=units.map(u=>{let arr=list.filter(x=>x.unit===u);return `<section class="unit-block"><header class="unit-heading"><span class="unit-mark">📚</span><div><small>${arr[0].subject==="science"?"العلوم":"الدراسات الاجتماعية"}</small><h3>${safe(u)}</h3></div><span class="unit-count">${arr.length} دروس</span></header><div class="unit-lessons">${arr.map(x=>`<article class="lesson-card lesson-row"><div class="lesson-index">${String(x.id).padStart(2,"0")}</div><div class="lesson-copy"><span class="tag ${x.subject==="science"?"tag-green":"tag-blue"}">${x.subject==="science"?"علوم":"دراسات"}</span><h3>${safe(x.title)}</h3><p>${safe(x.desc)}</p><div class="lesson-progress"><span style="width:${state.completed.includes(x.id)?100:0}%"></span></div><small>${state.completed.includes(x.id)?"تمت المذاكرة":"لم تبدأ بعد"} · ${x.questions.length} سؤالًا</small></div><div class="lesson-buttons"><button class="small-btn filled" data-study="${x.id}">📖 افتح صفحة الدرس</button><button class="small-btn" data-exam="${x.id}">✍ اختبار الدرس</button></div></article>`).join("")}</div></section>`}).join("");
 $$('[data-study]').forEach(b=>b.onclick=()=>openLesson(b.dataset.study));$$('[data-exam]').forEach(b=>b.onclick=()=>{openLesson(b.dataset.exam);setTimeout(()=>beginInlineLessonQuiz(),50)});
}
function closeMenu(){document.body.classList.remove("menu-open");$("#menuToggle").setAttribute("aria-expanded","false")}
function showPage(page,pushHistory=true){
 current=null;$("#lessonView").classList.add("hidden");$("#quizView").classList.add("hidden");$("#homeView").classList.remove("hidden");
 $$("#homeView [data-page]").forEach(el=>el.classList.toggle("hidden",el.dataset.page!==page));
 $$('[data-page-link]').forEach(a=>a.classList.toggle("active",a.dataset.pageLink===page));
 closeMenu();window.scrollTo(0,0);if(pushHistory)history.pushState({page},"",page==="home"?"#home":"#"+page);
}
function openLesson(id){
 current=lesson(id);if(!current)return;$("#homeView").classList.add("hidden");$("#quizView").classList.add("hidden");$("#lessonView").classList.remove("hidden");$("#inlineLessonQuiz").classList.add("hidden");
 $("#detailSubject").textContent=current.subject==="science"?"العلوم":"الدراسات الاجتماعية";$("#lessonBreadcrumb").textContent=current.unit;
 $("#detailTitle").textContent=current.title;$("#detailIntro").textContent=current.desc;
 $("#detailBody").innerHTML=current.body.split("\n\n").map(t=>`<p>${safe(t)}</p>`).join("");$("#detailBody").insertAdjacentHTML("afterbegin",`<div class="summary-label">✦ ملخص الدرس</div>`);
 const videoLink=current.video;$("#detailVideoTop").href=videoLink;
 const player=$("#detailVideoFrame"),fallback=$("#videoFallback");
 if(current.videoId){player.style.display="block";player.src="https://www.youtube-nocookie.com/embed/"+current.videoId;fallback.textContent="شاهد الفيديو داخل صفحة الدرس، ويمكنك تكبيره بملء الشاشة.";}
 else{player.removeAttribute("src");player.style.display="none";fallback.textContent="الفيديو المضمّن لهذا الدرس لم يُتحقق من رابطه بعد. اضغط على (فتح الفيديو على يوتيوب) لعرض نتائج شرح عنوان الدرس.";}
 $("#detailTest").onclick=beginInlineLessonQuiz;$("#finishLessonBtn").onclick=beginInlineLessonQuiz;
 $("#markDone").onclick=()=>beginInlineLessonQuiz();
 $("#detailKeywords").innerHTML=(current.subject==="science"?["المفهوم العلمي","التفسير","الأمثلة","التطبيق"]:["الموقع","الأسباب","الأحداث","النتائج"]).map(x=>`<span>${x}</span>`).join("");
 closeMenu();window.scrollTo(0,0);history.pushState({lesson:current.id},"","#lesson-"+current.id);
}
function beginInlineLessonQuiz(){if(!current)return;$("#inlineLessonQuiz").classList.remove("hidden");startQuiz([current],true);$("#inlineLessonQuiz").scrollIntoView({behavior:"smooth",block:"start"})}
function home(){showPage("home")}
function startQuiz(selected,inline=false){
 let pool=selected.flatMap(x=>x.questions.map(q=>({...q,sub:x.subject,title:x.title,lessonId:x.id})));
 if(selected.length>1 || selected.length===CURRICULUM.length) pool=pool.sort(()=>Math.random()-.5).slice(0,10);
 quiz=pool;qi=0;score=0;answered=false;inlineQuizMode=inline;quizTarget=inline?"#inlineQuizContent":"#quizContent";
 if(inline){$("#inlineLessonQuiz").classList.remove("hidden");renderQuestion();}
 else{$("#homeView").classList.add("hidden");$("#lessonView").classList.add("hidden");$("#quizView").classList.remove("hidden");renderQuestion();window.scrollTo(0,0)}
}
function renderQuestion(){
 let box=$(quizTarget);
 if(qi>=quiz.length){let earned=score*3;
  state.points+=earned;state.tests++;
  if(inlineQuizMode&&current&&!state.completed.includes(current.id)){state.completed.push(current.id);state.points+=5;}
  save();let completedMsg=inlineQuizMode?"تم تسجيل إكمال الدرس وإضافة 5 نقاط للمذاكرة.":"";
  box.innerHTML=`<div class="result-hero"><div class="result-icon">🎉</div><h2>انتهى الاختبار</h2><strong>${score} / ${quiz.length}</strong><p>حصلت على ${earned} نقطة من إجاباتك الصحيحة</p><div class="result-track"><span style="width:${score/quiz.length*100}%"></span></div><p>${score===quiz.length?"ممتاز! إجاباتك كلها صحيحة.":"راجع إجاباتك ثم أعد المحاولة لتحسن نتيجتك."}</p><p>${completedMsg}</p><button class="primary-btn" id="again">إعادة الاختبار</button><button class="soft-light-btn" id="toHome">العودة للمنصة</button></div>`;
  $("#again").onclick=()=>startQuiz(inlineQuizMode&&current?[current]:CURRICULUM,inlineQuizMode);$("#toHome").onclick=home;return}
 let q=quiz[qi];answered=false;box.innerHTML=`<div class="quiz-progress-head"><span>${q.sub==="science"?"العلوم":"الدراسات الاجتماعية"} · ${safe(q.title)}</span><b>السؤال ${qi+1} من ${quiz.length}</b></div><div class="quiz-progress"><span style="width:${qi/quiz.length*100}%"></span></div><h2>${safe(q.q)}</h2><div class="answer-list">${q.a.map((a,i)=>`<button class="answer-option" data-answer="${i}"><i>${letters[i]}</i>${safe(a)}</button>`).join("")}</div><div id="feedback"></div><button class="primary-btn hidden" id="next">السؤال التالي ←</button>`;
 box.querySelectorAll("[data-answer]").forEach(b=>b.onclick=()=>answer(+b.dataset.answer));
}
function answer(i){if(answered)return;answered=true;let q=quiz[qi],ok=i===q.c;if(ok)score++;let box=$(quizTarget);box.querySelectorAll("[data-answer]").forEach((b,n)=>{b.disabled=true;if(n===q.c)b.classList.add("correct");if(n===i&&!ok)b.classList.add("wrong")});box.querySelector("#feedback").innerHTML=`<div class="feedback ${ok?"good":"bad"}"><b>${ok?"إجابة صحيحة ✓":"الإجابة الصحيحة موضحة بالأخضر"}</b><p>${safe(q.e)}</p></div>`;box.querySelector("#next").classList.remove("hidden");box.querySelector("#next").onclick=()=>{qi++;renderQuestion()}}
function renderVideos(){let arr=CURRICULUM;$("#videoGrid").innerHTML=arr.map(x=>`<article class="video-card"><span class="play-icon">▶</span><div><b>${safe(x.title)}</b><small>${x.subject==="science"?"علوم":"دراسات"} · ثالثة إعدادي</small><button class="text-btn" data-open-video="${x.id}">افتح صفحة الدرس والفيديو ←</button></div></article>`).join("");$$('[data-open-video]').forEach(b=>b.onclick=()=>openLesson(b.dataset.openVideo))}
$("#detailBack").onclick=()=>showPage("lessons");$("#homeBrand").onclick=e=>{e.preventDefault();home()};$("#backSubjects").onclick=()=>{subject="all";renderLessons()};
$$('[data-subject]').forEach(b=>b.onclick=()=>{subject=b.dataset.subject;renderLessons();showPage("lessons")});
$$('[data-scroll]').forEach(b=>b.onclick=()=>showPage(b.dataset.scroll==="leaderboard"?"leaderboard":"subjects"));
$$('[data-page-link]').forEach(a=>a.onclick=e=>{e.preventDefault();let pg=a.dataset.pageLink;if(pg==="lessons")subject="all";renderLessons();showPage(pg)});
$("#menuToggle").onclick=()=>{let on=document.body.classList.toggle("menu-open");$("#menuToggle").setAttribute("aria-expanded",String(on))};$("#navBackdrop").onclick=closeMenu;
$("#startQuizBtn").onclick=()=>startQuiz(CURRICULUM);
$("#themeBtn").onclick=()=>{document.body.classList.toggle("dark");localStorage.setItem("eduworld_dark",document.body.classList.contains("dark")?"1":"0")};
$("#profileBtn").onclick=()=>notify("تسجيل الحسابات والملف الشخصي سيتفعّلان بعد ربط قاعدة البيانات.");
$("#quizBack").onclick=home;window.addEventListener("popstate",()=>{if(location.hash.startsWith("#lesson-")){let id=location.hash.split("-").pop();openLesson(id)}else{let pg=location.hash.replace("#","");showPage(["subjects","lessons","tests","leaderboard","videos"].includes(pg)?pg:"home",false)}});
if(localStorage.getItem("eduworld_dark")==="1")document.body.classList.add("dark");
stats();renderBoard();renderLessons();renderVideos();showPage("home");
